    # band colors: per band, majority nonzero non-line color among its cells (excluding template source band?)
    def band_color(r0,r1,c0,c1):
        vals=[int(x) for x in g[r0:r1,c0:c1].flat if x not in (0,lc)]
        if not vals: return None
        return max(set(vals), key=vals.count)
    colors={}
    for ri in range(len(rb)-1):
        for ci in range(len(cb)-1):
            r0,r1=rb[ri]+1,rb[ri+1]; c0,c1=cb[ci]+1,cb[ci+1]
            bc=band_color(r0,r1,c0,c1)
            colors[(ri,ci)]=bc
    for ri in range(len(rb)-1):
        for ci in range(len(cb)-1):
            r0,r1=rb[ri]+1,rb[ri+1]; c0,c1=cb[ci]+1,cb[ci+1]
