from collections import Counter
def solve(gi):
    g=[list(r) for r in gi]; h=len(g); w=len(g[0])
    sr=[r for r in range(h) if len(set(g[r]))==1]
    sc=[c for c in range(w) if len(set([g[r][c] for r in range(h)]))==1]
    Rb=[-1]+sr+[h]; Cb=[-1]+sc+[w]
    # band color per block: most common nonzero non-separator value in that block
    blocks={}
    for i,(r0,r1) in enumerate(zip(Rb,Rb[1:])):
        for j,(c0,c1) in enumerate(zip(Cb,Cb[1:])):
            vals=[g[a][b] for a in range(r0,r1) for b in range(c0,c1) if g[a][b]!=0 and b not in sc]
