    out=[row[:] for row in g]
    for i,(r0,r1) in enumerate(zip(Rb,Rb[1:])):
        col=blocks[(i,0)]
        for a in range(r0,r1):
            for b in range(w):
                if b not in sc: out[a][b]=col
    return out
